int comparar_ints(const void *a, const void *b) {
    // Converte os ponteiros genéricos (void*) para ponteiros de int e compara
    int int_a = *(const int *)a;
    int int_b = *(const int *)b;

    if (int_a < int_b) return -1;
    if (int_a > int_b) return 1;
    return 0;
}

